from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Ssh_ftm_enable(EmssimCommand):
    def __init__(self, method="ssh_ftm_enable", timeout=60, rpc_connection_name='localRPC'):
        super(Ssh_ftm_enable, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Ssh_ftm_enable, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "ssh_info"):
                self._ret['ssh_status'] = data["status"]
                self._ret['details'] = data["details"]
        elif ("status" in data):
            self._ret["status"] = data["status"]
